INSERT INTO events (id, title, description, latitude, longitude, likes, dislikes, closes_at) VALUES
(101, 'Bargate Quarter: new homes, shops and a square by the medieval walls', 'The former Bargate Shopping Centre has been demolished and the site next to the medieval Bargate is being rebuilt as Bargate Quarter: new homes, shops and places to eat, with views opened up to a stretch of the old town walls and new walking routes between the High Street and the Old Town. Tell us what would make the new public spaces work for you.', 50.9030, -1.4040, 88, 21, '2026-11-20T17:00:00Z'),
(102, 'Portswood Broadway: bus gate and wider pavements', 'The Portswood Broadway scheme, funded through the Transforming Cities Fund, made a short section of Portswood Road bus, cycle and taxi only, widened the pavements outside the shops and added new crossings, sending through traffic around the main roads instead. The scheme has divided opinion. We want to hear from shoppers, traders, bus users and people living on nearby streets about what should happen next.', 50.9250, -1.3915, 41, 63, '2026-11-08T17:00:00Z'),
(103, 'Itchen Bridge toll changes', 'Tolls on the Itchen Bridge pay for the upkeep of the bridge. The proposal raises cash tolls for cars at peak times, with a lower rate for drivers who register for a bridge account. Walking and cycling across the bridge stays free. Tell us how the change would affect your journeys between Woolston and the city centre.', 50.8985, -1.3880, 18, 77, '2026-10-30T17:00:00Z'),
(104, 'Centenary Quay, Woolston: final riverside phase', 'Centenary Quay is the regeneration of the former Vosper Thornycroft shipyard in Woolston. The last phase would add more homes, finish the riverside promenade along the Itchen and create a small park and play area by the water.', 50.8960, -1.3810, 52, 14, '2026-12-04T17:00:00Z'),
(105, 'Royal Pier waterfront and Mayflower Park', 'Plans to reconnect the city centre with the water at Royal Pier have been discussed for many years. Ideas include a bigger, better-equipped Mayflower Park, a waterfront walking and cycling route, new homes and leisure space, while keeping the Red Funnel and Town Quay ferry links working. Which parts matter most to you?', 50.8952, -1.4062, 73, 30, '2027-01-15T17:00:00Z'),
(106, 'Southampton Central: northern forecourt and Station Quarter', 'The Station Quarter improvements at Southampton Central give the north side of the station a new forecourt with better taxi and drop-off space, clearer bus stops, more cycle parking and safer crossings towards the city centre and Shirley.', 50.9077, -1.4140, 64, 9, '2026-11-27T17:00:00Z'),
(107, 'Townhill Park estate regeneration', 'The Townhill Park regeneration replaces older council blocks in phases with new, energy-efficient homes, including council homes, alongside a new community space and greener walking routes. Phasing is planned so existing tenants can move once, into a new home on the estate where possible.', 50.9315, -1.3600, 47, 26, '2026-12-11T17:00:00Z'),
(108, 'Burgess Road cycle lanes and crossings', 'Part of the Southampton Cycle Network: the plan adds kerb-separated cycle lanes on Burgess Road near the university, upgrades two crossings and moves some bus stops to make room. Some on-street parking near the shops would be removed.', 50.9330, -1.3995, 54, 49, '2026-11-13T17:00:00Z'),
(109, 'Cleaner air on the Western Approach', 'Southampton chose not to introduce a charging clean air zone. Instead the council has used measures such as cleaner buses, support for taxi drivers to switch to low-emission vehicles and work with the port on lorry emissions. We want views on what to do next along the Western Approach and Millbrook Road.', 50.9110, -1.4250, 47, 22, '2026-10-10T17:00:00Z'),
(110, 'School Streets in Shirley', 'Under the School Streets programme, the road outside a primary school closes to through traffic for about 45 minutes at drop-off and pick-up. Residents, blue badge holders and deliveries to homes on the street can still get through. Should more schools in Shirley join?', 50.9220, -1.4300, 69, 17, '2026-11-30T17:00:00Z'),
(111, 'Weston Shore sea wall and promenade repairs', 'Damaged sections of the sea wall along Weston Shore would be repaired and raised in places to cope with higher tides, with a resurfaced promenade, new benches and better access down to the beach.', 50.8880, -1.3770, 58, 4, '2026-09-25T17:00:00Z'),
(112, 'Guildhall Square: greener and better for events', 'Guildhall Square sits at the heart of the Cultural Quarter, next to MAST Mayflower Studios and the John Hansard Gallery. The proposal adds trees and planters, more seating and shade, and permanent power points so the square is easier to use for markets, screenings and festivals.', 50.9087, -1.4050, 61, 12, '2026-12-18T17:00:00Z'),
(113, 'After the City of Culture 2025 bid: which projects should still go ahead?', 'Southampton reached the final shortlist to be UK City of Culture 2025, alongside Bradford, County Durham and Wrexham. The title went to Bradford. Many projects planned for the bid could still happen at a smaller scale. Tell us which ones you would most like to see: festivals, public art, youth programmes or community events.', 50.9095, -1.4040, 96, 18, '2026-01-31T17:00:00Z'),
(114, 'Mayflower Memorial and the Western Esplanade', 'The Mayflower sailed from Southampton in 1620, and the city marked the 400th anniversary with Mayflower 400 events. The memorial on the Western Esplanade sits on a busy road beside the old town walls. The proposal improves the setting with better crossings, information boards and planting.', 50.8968, -1.4080, 57, 11, '2026-12-01T17:00:00Z'),
(115, 'Former Leisure World site, West Quay Road', 'The Leisure World entertainment complex on West Quay Road, once home to a cinema, bowling and nightclubs, has closed and been cleared. The site is proposed for new homes with ground-floor shops and cafés, and a new walking route from West Quay Road towards the waterfront.', 50.9045, -1.4105, 34, 29, '2026-12-08T17:00:00Z'),
(116, 'Watermark WestQuay: evening safety and public spaces', 'Watermark WestQuay opened beside the old town walls with a cinema, restaurants and a public plaza. We are asking how the plaza and the routes to it feel in the evening, and whether lighting, seating or security should change.', 50.9035, -1.4090, 48, 15, '2026-11-24T17:00:00Z'),
(117, 'Kingsland Square and market, St Mary''s', 'Kingsland Square in St Mary''s hosts the Kingsland Market. The proposal improves the square with new paving, trees, seating and permanent market pitches, and better links to St Mary Street.', 50.9070, -1.3960, 39, 8, '2026-12-15T17:00:00Z'),
(118, 'Ocean Village waterfront walkway', 'Ocean Village has changed a lot, with the Harbour Hotel, new apartments and the marina. The proposal opens up a continuous public walkway around the marina edge, with seating and better signs from Canute Road.', 50.8940, -1.3925, 42, 19, '2026-11-19T17:00:00Z'),
(119, 'Southampton Airport runway extension: noise and flight paths', 'An extension to the runway at Southampton Airport was approved by Eastleigh Borough Council in 2021. The airport sits just outside the city, and residents in Swaythling, Bassett and Townhill Park are under the flight paths. We want to know how aircraft noise affects you and what monitoring and limits you would like the council to push for.', 50.9455, -1.3620, 37, 58, '2026-11-06T17:00:00Z'),
(120, 'Old Town walls: repairs and better access', 'Southampton''s medieval town walls are among the most complete in England. Several sections need stone repairs, and the proposal also adds better lighting, signs and a step-free route to the walkway on top of the walls where possible.', 50.8990, -1.4015, 46, 13, '2026-12-05T17:00:00Z'),
(121, 'SeaCity Museum: free entry for residents', 'SeaCity Museum in the Civic Centre tells the story of the city and its people, including the crew of the Titanic, many of whom came from Southampton. The proposal offers free or reduced entry for Southampton residents and more school visits.', 50.9060, -1.4060, 55, 7, '2026-12-20T17:00:00Z'),
(122, 'Hoglands Park skatepark refresh', 'The skatepark in Hoglands Park is one of the best-used spaces for young people in the city centre. The proposal resurfaces and extends it, adds lighting so it can be used on winter evenings and improves the seating around it.', 50.9090, -1.4020, 28, 6, '2026-11-26T17:00:00Z'),
(123, 'Southampton Sports Centre, Bassett: track and facilities upgrade', 'Southampton Sports Centre in Bassett has an athletics track, playing fields and the outdoor ski slope. The proposal resurfaces the track, upgrades the changing rooms and improves bus and cycle links to the site.', 50.9395, -1.4180, 44, 10, '2026-12-09T17:00:00Z'),
(124, 'Matchday parking controls around St Mary''s Stadium', 'On Southampton FC matchdays, streets in Northam, St Mary''s and Bevois Valley fill with parked cars. The proposal extends the matchday permit zone and adds traffic marshals on the busiest roads.', 50.9060, -1.3910, 31, 44, '2026-11-04T17:00:00Z'),
(125, 'E-scooter and e-bike rental: should the scheme continue?', 'Southampton has taken part in the national rental e-scooter trials as part of the Solent Future Transport Zone. We want your views on whether rental e-scooters and e-bikes should stay, where they should be parked and how pavement riding should be tackled.', 50.9105, -1.4000, 38, 33, '2026-11-17T17:00:00Z'),
(126, 'Garden waste collection charge', 'Garden waste is collected through an opt-in subscription. The proposal changes the yearly charge and adds a reduced rate for households on council tax support. Collections would stay fortnightly from spring to autumn.', 50.9140, -1.4010, 22, 51, '2026-11-10T17:00:00Z'),
(127, 'Weekly food waste collections', 'Councils in England must start collecting food waste separately every week. Each household would get a small kitchen caddy and an outdoor bin, collected weekly, and the food waste would be used to make energy and fertiliser.', 50.9180, -1.4090, 63, 21, '2026-12-03T17:00:00Z'),
(128, 'Road resurfacing and pothole repairs 2026-27', 'Each year the council chooses which roads to resurface and how to prioritise pothole repairs. Tell us which roads and pavements near you are in the worst state, and whether cycle lanes and pavements should get a bigger share.', 50.9250, -1.4180, 72, 9, '2026-11-28T17:00:00Z'),
(129, 'Budget 2026-27: savings and council tax', 'Like many councils, Southampton faces a large gap between what services cost and the money it receives. The consultation sets out options for savings, changes to some services and the level of council tax for next year.', 50.9135, -1.4030, 19, 66, '2026-01-20T17:00:00Z'),
(130, 'Shirley High Street improvements', 'Shirley High Street has a wide mix of shops and cafés. The proposal widens pavements in the busiest section, plants trees, adds seating and short-stay loading bays, and improves the crossings near the precinct.', 50.9230, -1.4320, 49, 12, '2026-12-12T17:00:00Z'),
(131, 'Bitterne precinct refresh', 'Bitterne precinct has empty units and tired paving. The proposal resurfaces the precinct, adds planting and lighting, and offers lower-rent pop-up units to local businesses.', 50.9180, -1.3700, 36, 14, '2026-12-02T17:00:00Z'),
(132, 'Lordshill district centre: new library and community hub', 'The proposal brings the library, a community hall and health services together in one building at the Lordshill district centre, with better paths from the surrounding estates and a safer car park.', 50.9360, -1.4420, 33, 17, '2026-11-21T17:00:00Z'),
(133, 'Thornhill estate: green spaces and play areas', 'The proposal improves the green spaces across the Thornhill estate: new play equipment, a community growing area, better footpaths and lighting, and more bins.', 50.9115, -1.3500, 40, 22, '2026-12-10T17:00:00Z'),
(134, 'Above Bar Street: a better city centre high street', 'Above Bar Street is the main shopping street between the Bargate and the Civic Centre. The proposal adds trees, seating and play features, encourages cafés to use outdoor space and makes it easier to cross between the shops and the parks.', 50.9080, -1.4045, 52, 24, '2026-12-17T17:00:00Z'),
(135, 'Electric vehicle chargers on residential streets', 'Many homes in Southampton have no driveway. The proposal installs on-street chargers in lamp posts and dedicated bays across Shirley, Freemantle, Portswood and Bitterne, chosen with residents.', 50.9150, -1.4380, 35, 20, '2026-12-07T17:00:00Z'),
(136, 'Bus route changes: evening and Sunday services', 'Bus operators in the city, including Bluestar, First and the Unilink services, are reviewing evening and Sunday timetables. The council can support some routes. Tell us which journeys you rely on and where gaps in the network cause you problems.', 50.9300, -1.3960, 29, 42, '2026-11-12T17:00:00Z'),
(137, 'The Avenue: safer cycling past the Common', 'The Avenue is one of the main routes into the city past Southampton Common. The proposal upgrades the existing cycle lanes with kerb separation, improves the junctions at Highfield Lane and Bassett Avenue, and keeps the bus lanes.', 50.9285, -1.4120, 47, 26, '2026-11-25T17:00:00Z'),
(138, 'Southampton Common: lakes, paths and wildlife areas', 'Southampton Common is a large open space and nature area in the north of the city. The proposal cleans and restores the boating lake and Ornamental Lake, repairs the main paths, adds benches and protects wildflower areas.', 50.9265, -1.4100, 81, 6, '2026-12-14T17:00:00Z'),
(139, 'Flood defences along the River Test at Millbrook and Redbridge', 'Low-lying areas near the River Test at Millbrook and Redbridge are at growing risk of tidal flooding. The proposal raises flood walls and embankments and improves drainage, working with the Environment Agency.', 50.9175, -1.4455, 54, 5, '2026-12-06T17:00:00Z'),
(140, 'Tackling fly-tipping in Bevois Valley and Portswood', 'Fly-tipping is a growing problem in back alleys and on side streets in Bevois Valley and Portswood. The proposal adds mobile CCTV at hotspots, bulky waste amnesty days and faster clearance.', 50.9175, -1.3960, 58, 10, '2026-11-29T17:00:00Z'),
(141, 'Cobden Bridge and Bitterne Park Triangle', 'Cobden Bridge links Bitterne Park and Portswood across the River Itchen. The proposal repairs the bridge, widens the pavement on one side and makes the junction at the Bitterne Park Triangle safer for people walking and cycling.', 50.9245, -1.3800, 33, 11, '2026-12-16T17:00:00Z'),
(142, 'Northam Bridge refurbishment and weight limit', 'Northam Bridge carries traffic across the Itchen between Northam and Bitterne. The proposal strengthens the bridge and introduces a temporary weight limit and lane closures while the work is done.', 50.9135, -1.3900, 26, 31, '2026-11-23T17:00:00Z'),
(143, 'Tudor House and Garden: longer opening and community events', 'Tudor House and Garden is one of Southampton''s oldest buildings, in the heart of the Old Town. The proposal extends opening hours, hosts more community events in the garden and improves step-free access.', 50.8975, -1.4048, 44, 4, '2026-12-19T17:00:00Z'),
(144, 'Houses in multiple occupation: tighter rules in Portswood and Highfield', 'Portswood, Highfield and Swaythling have a high number of shared houses, many let to students. The proposal tightens planning controls on new houses in multiple occupation and adds licensing standards for landlords.', 50.9325, -1.3900, 21, 37, '2026-11-16T17:00:00Z'),
(145, 'Bargate and Hanover Buildings: safer crossings and fewer buses', 'Buses still run past the medieval Bargate along Hanover Buildings and Vincent''s Walk. The proposal moves some bus stops to reduce crowding, adds a wider crossing between Above Bar and the High Street and protects the Bargate from vehicle damage.', 50.9010, -1.4015, 43, 9, '2026-12-21T17:00:00Z'),
(146, 'Millbrook and Redbridge: safer walking routes to schools', 'Children in Millbrook and Redbridge have to cross busy roads to reach school. The proposal adds new crossings, wider footpaths and a 20mph limit on residential streets around the schools.', 50.9035, -1.4400, 39, 16, '2026-12-13T17:00:00Z'),
(147, 'Public toilets in the city centre', 'Several public toilets in the city centre and parks have closed or have limited hours. The proposal reopens toilets in key parks, adds a community toilet scheme with local businesses and improves signage.', 50.9050, -1.4030, 67, 8, '2026-12-22T17:00:00Z'),
(148, 'Street trees: planting 1,000 more across the city', 'The proposal plants more street trees across the city, prioritising areas with the fewest trees and the hottest streets in summer. Residents can request a tree outside their home.', 50.9200, -1.4250, 31, 19, '2026-11-18T17:00:00Z')
